use std::collections::HashSet;

use anyhow::Result;
use serde_json::{json, Map, Value};

use crate::{CapabilitySpec, EntitySpec, FieldSpec, ScaffoldInput};

const RISK_READ: &str = "read";
const RISK_WRITE_REVERSIBLE: &str = "write_reversible";
const RISK_WRITE_DESTRUCTIVE: &str = "write_destructive";

/// Fixed tag that marks a manifest as generated by the WorldBase scaffold so
/// the host can recognise the project as a WorldBase local application.
const SCAFFOLD_APP_TAG: &str = "worldbase.scaffold";

const READ_DEADLINE_MS: u64 = 5_000;
const WRITE_DEADLINE_MS: u64 = 10_000;

/// Build the capability list for the project: one health capability plus the
/// six CRUD/search operations for every declared entity.
pub fn build_capabilities(input: &ScaffoldInput) -> Result<Vec<CapabilitySpec>> {
    if !input.ai_integration {
        return Ok(Vec::new());
    }
    let mut capabilities = Vec::with_capacity(1 + input.entities.len() * 6);
    capabilities.push(health_capability(input));
    for entity in &input.entities {
        capabilities.extend(entity_capabilities(input, entity));
    }
    Ok(capabilities)
}

/// Serialize the platform manifest from the same capability specs.
pub fn manifest_json(input: &ScaffoldInput, capabilities: &[CapabilitySpec]) -> Value {
    let caps = capabilities
        .iter()
        .map(|capability| {
            let mut value = json!({
                "id": capability.id,
                "title": capability.title,
                "description": capability.description,
                "inputSchema": capability.input_schema,
                "operation": capability.operation,
                "risk": capability.risk,
                "permissions": [],
                "dataScopes": ["project"],
                "sideEffects": capability.side_effects,
                "idempotent": capability.idempotent,
                "deadlineMs": deadline_for(&capability.risk),
                "tags": capability.tags,
            });
            if let Some(output_schema) = &capability.output_schema {
                value["outputSchema"] = output_schema.clone();
            }
            value
        })
        .collect::<Vec<_>>();

    let mut manifest = json!({
        "schemaVersion": 1,
        "app": {
            "id": input.app_id(),
            "name": input.name,
            "version": "0.1.0",
            "description": format!(
                "{} ({}) managed application with AI capabilities",
                input.name, input.project_type
            ),
            "tags": app_tags(input),
            "platforms": ["desktop"],
            "trustLevel": "untrusted",
        },
        "runtime": {
            "kind": "managed_project",
            "activation": "on-demand",
            "healthCheck": "app.health",
        },
        "capabilities": caps,
    });
    if capabilities.is_empty() {
        manifest["aiIntegration"] = json!("none");
        manifest["runtime"] = json!({
            "kind": "managed_project",
            "activation": "on-demand",
        });
    }
    manifest
}

fn health_capability(input: &ScaffoldInput) -> CapabilitySpec {
    CapabilitySpec {
        id: "app.health".to_string(),
        title: "Application health".to_string(),
        description: format!("Health check for {} ({}).", input.name, input.project_type),
        input_schema: object_schema(Map::new(), Vec::new()),
        output_schema: Some(object_schema(
            properties_from([
                ("status", json!({ "type": "string" })),
                ("appId", json!({ "type": "string" })),
            ]),
            vec!["status".to_string(), "appId".to_string()],
        )),
        risk: RISK_READ.to_string(),
        side_effects: false,
        idempotent: true,
        operation: "app.health".to_string(),
        tags: health_tags(input),
    }
}

fn entity_capabilities(input: &ScaffoldInput, entity: &EntitySpec) -> Vec<CapabilitySpec> {
    let snake = entity.snake();
    let entity_output = entity_output_schema(entity);

    vec![
        CapabilitySpec {
            id: format!("{snake}.list"),
            title: format!("List {} records", entity.name),
            description: format!(
                "List {} records for {} ({}).",
                entity.name, input.name, input.project_type
            ),
            input_schema: list_input_schema(),
            output_schema: Some(list_output_schema(entity)),
            risk: RISK_READ.to_string(),
            side_effects: false,
            idempotent: true,
            operation: format!("{snake}.list"),
            tags: entity_tags(input, entity, "list", RISK_READ),
        },
        CapabilitySpec {
            id: format!("{snake}.get"),
            title: format!("Get a {} record", entity.name),
            description: format!(
                "Fetch a single {} record by id for {} ({}).",
                entity.name, input.name, input.project_type
            ),
            input_schema: id_input_schema(),
            output_schema: Some(entity_output.clone()),
            risk: RISK_READ.to_string(),
            side_effects: false,
            idempotent: true,
            operation: format!("{snake}.get"),
            tags: entity_tags(input, entity, "get", RISK_READ),
        },
        CapabilitySpec {
            id: format!("{snake}.create"),
            title: format!("Create a {} record", entity.name),
            description: format!(
                "Create a new {} record in {} ({}).",
                entity.name, input.name, input.project_type
            ),
            input_schema: create_input_schema(entity),
            output_schema: Some(entity_output.clone()),
            risk: RISK_WRITE_REVERSIBLE.to_string(),
            side_effects: true,
            idempotent: false,
            operation: format!("{snake}.create"),
            tags: entity_tags(input, entity, "create", RISK_WRITE_REVERSIBLE),
        },
        CapabilitySpec {
            id: format!("{snake}.update"),
            title: format!("Update a {} record", entity.name),
            description: format!(
                "Update an existing {} record by id for {} ({}).",
                entity.name, input.name, input.project_type
            ),
            input_schema: update_input_schema(entity),
            output_schema: Some(entity_output.clone()),
            risk: RISK_WRITE_REVERSIBLE.to_string(),
            side_effects: true,
            idempotent: true,
            operation: format!("{snake}.update"),
            tags: entity_tags(input, entity, "update", RISK_WRITE_REVERSIBLE),
        },
        CapabilitySpec {
            id: format!("{snake}.remove"),
            title: format!("Remove a {} record", entity.name),
            description: format!(
                "Remove {} record by id for {} ({}). This is a destructive write.",
                entity.name, input.name, input.project_type
            ),
            input_schema: id_input_schema(),
            output_schema: Some(remove_output_schema()),
            risk: RISK_WRITE_DESTRUCTIVE.to_string(),
            side_effects: true,
            idempotent: false,
            operation: format!("{snake}.remove"),
            tags: entity_tags(input, entity, "remove", RISK_WRITE_DESTRUCTIVE),
        },
        CapabilitySpec {
            id: format!("{snake}.search"),
            title: format!("Search {} records", entity.name),
            description: format!(
                "Search {} records in {} matching a text query.",
                entity.name, input.name
            ),
            input_schema: search_input_schema(),
            output_schema: Some(list_output_schema(entity)),
            risk: RISK_READ.to_string(),
            side_effects: false,
            idempotent: true,
            operation: format!("{snake}.search"),
            tags: entity_tags(input, entity, "search", RISK_READ),
        },
    ]
}

fn object_schema(properties: Map<String, Value>, required: Vec<String>) -> Value {
    let mut schema = Map::new();
    schema.insert("type".to_string(), json!("object"));
    schema.insert("properties".to_string(), Value::Object(properties));
    if !required.is_empty() {
        schema.insert("required".to_string(), json!(required));
    }
    schema.insert("additionalProperties".to_string(), json!(false));
    Value::Object(schema)
}

fn properties_from<const N: usize>(entries: [(&str, Value); N]) -> Map<String, Value> {
    entries
        .into_iter()
        .map(|(key, value)| (key.to_string(), value))
        .collect()
}

fn field_schema(field: &FieldSpec) -> Value {
    json!({ "type": field.input_type() })
}

fn entity_output_schema(entity: &EntitySpec) -> Value {
    let mut properties = Map::new();
    let mut required = Vec::new();
    for field in crate::templates::effective_fields(entity) {
        let mut schema = field_schema(&field);
        if !field.primary_key && !field.required {
            if let Some(type_value) = schema.get("type").cloned() {
                schema["type"] = json!([type_value, "null"]);
            }
        }
        properties.insert(field.name.clone(), schema);
        if field.primary_key || field.required {
            required.push(field.name.clone());
        }
    }
    object_schema(properties, required)
}

fn list_input_schema() -> Value {
    object_schema(
        properties_from([
            (
                "limit",
                json!({ "type": "integer", "minimum": 1, "maximum": 200 }),
            ),
            ("offset", json!({ "type": "integer", "minimum": 0 })),
            ("orderBy", json!({ "type": "string" })),
            (
                "orderDirection",
                json!({ "type": "string", "enum": ["asc", "desc"] }),
            ),
        ]),
        Vec::new(),
    )
}

fn list_output_schema(entity: &EntitySpec) -> Value {
    object_schema(
        properties_from([
            (
                "items",
                json!({ "type": "array", "items": entity_output_schema(entity) }),
            ),
            ("total", json!({ "type": "integer", "minimum": 0 })),
        ]),
        vec!["items".to_string(), "total".to_string()],
    )
}

fn id_input_schema() -> Value {
    object_schema(
        properties_from([("id", json!({ "type": "string", "minLength": 1 }))]),
        vec!["id".to_string()],
    )
}

fn create_input_schema(entity: &EntitySpec) -> Value {
    let mut properties = Map::new();
    let mut required = Vec::new();
    for field in entity.writable_fields() {
        properties.insert(field.name.clone(), field_schema(field));
        if field.required {
            required.push(field.name.clone());
        }
    }
    object_schema(properties, required)
}

fn update_input_schema(entity: &EntitySpec) -> Value {
    let mut properties = Map::new();
    for field in entity.writable_fields() {
        properties.insert(field.name.clone(), field_schema(field));
    }
    properties.insert(
        "id".to_string(),
        json!({ "type": "string", "minLength": 1 }),
    );
    object_schema(properties, vec!["id".to_string()])
}

fn remove_output_schema() -> Value {
    object_schema(
        properties_from([
            ("id", json!({ "type": "string" })),
            ("deleted", json!({ "type": "boolean" })),
        ]),
        vec!["id".to_string(), "deleted".to_string()],
    )
}

fn search_input_schema() -> Value {
    object_schema(
        properties_from([("query", json!({ "type": "string", "minLength": 1 }))]),
        vec!["query".to_string()],
    )
}

fn deadline_for(risk: &str) -> u64 {
    if risk == RISK_READ {
        READ_DEADLINE_MS
    } else {
        WRITE_DEADLINE_MS
    }
}

fn health_tags(input: &ScaffoldInput) -> Vec<String> {
    let mut tags = vec![
        "app.health".to_string(),
        "health".to_string(),
        RISK_READ.to_string(),
        input.name.clone(),
        input.project_type.clone(),
        input.template.clone(),
    ];
    dedup(&mut tags);
    tags
}

fn entity_tags(
    input: &ScaffoldInput,
    entity: &EntitySpec,
    operation: &str,
    risk: &str,
) -> Vec<String> {
    let mut tags = vec![
        entity.snake(),
        entity.table.clone(),
        entity.name.clone(),
        operation.to_string(),
        risk.to_string(),
        input.name.clone(),
        input.project_type.clone(),
        input.template.clone(),
    ];
    dedup(&mut tags);
    tags
}

fn app_tags(input: &ScaffoldInput) -> Vec<String> {
    let mut tags = vec![
        SCAFFOLD_APP_TAG.to_string(),
        input.template.clone(),
        input.project_type.clone(),
        input.name.clone(),
    ];
    for entity in &input.entities {
        tags.push(entity.name.clone());
        tags.push(entity.snake());
        tags.push(entity.table.clone());
    }
    dedup(&mut tags);
    tags
}

fn dedup(values: &mut Vec<String>) {
    let mut seen = HashSet::new();
    values.retain(|value| !value.is_empty() && seen.insert(value.clone()));
}
